public class TaggedCacheService
{
    private readonly IDistributedCache _cache;
    private readonly IDatabase _redis;
    private const string TagPrefix = "tag:";

    public TaggedCacheService(
        IDistributedCache cache,
        IConnectionMultiplexer redis)
    {
        _cache = cache;
        _redis = redis.GetDatabase();
    }

    public async Task SetAsync(
        string key,
        string value,
        string[] tags,
        DistributedCacheEntryOptions? options = null)
    {
        await _cache.SetStringAsync(key, value, options ?? new());

        foreach (var tag in tags)
        {
            await _redis.SetAddAsync($"{TagPrefix}{tag}", key);
        }
    }

    public async Task InvalidateByTagAsync(string tag)
    {
        var setKey = $"{TagPrefix}{tag}";
        var keys = await _redis.SetMembersAsync(setKey);

        var tasks = keys.Select(k => _cache.RemoveAsync(Encoding.UTF8.GetString(k)));
        await Task.WhenAll(tasks);

        await _redis.KeyDeleteAsync(setKey);
    }
}
